import {initialState,reduce,validateState,correctResearch,readyToLeave,heardEssentials,ITEM_IDS} from './state.js';
import {sources as baseSources,slots as baseSlots,items as baseItems,dialogue as baseDialogue,hints as baseHints} from './data.js';
import {CHANNEL_SOLUTION,channelOpenings,traceChannels} from './channels.js';
import {gardenDialogue as baseGardenDialogue} from './data.js';
import {t,getLanguage,setLanguage,localize,LANGUAGES} from './i18n.js';
let sources,slots,items,dialogue,hints,gardenDialogue;
let offlineMessage='Offline-Version wird vorbereitet …';
function refreshContent(){sources=localize(baseSources);slots=localize(baseSlots);items=localize(baseItems);dialogue=localize(baseDialogue);hints=localize(baseHints);gardenDialogue=localize(baseGardenDialogue);}
refreshContent();
const KEY='tamatem-dina-prolog-v1';
const $=s=>document.querySelector(s);
const asset=name=>globalThis.TD_ASSETS?.[name]||'./assets/'+name;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=initialState(),savedAt=null,storageAvailable=true,feedback='',showMarkers=true,toastTimer;
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved){state=validateState(saved.state);savedAt=saved.savedAt;}}catch{storageAvailable=false;}
const icons={book:'<path d="M3 5q5-2 9 1 4-3 9-1v15q-5-2-9 1-4-3-9-1Z"/><path d="M12 6v15"/>',leaf:'<path d="M5 19C-1 7 10 2 21 3c0 11-5 20-16 16ZM5 19 16 8"/>',map:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2ZM9 3v16M15 5v16"/>',flower:'<circle cx="12" cy="12" r="2"/><path d="M12 10C2 0 21-2 14 10 27 3 28 20 14 14 21 27 3 28 10 14-3 20-3 3 10 10 3-3 21-3 12 10Z"/>',paper:'<path d="M5 2h10l4 4v16H5ZM15 2v5h4M8 11h8M8 15h8M8 19h5"/>',lens:'<circle cx="10" cy="10" r="7"/><path d="m15 15 7 7"/>',lantern:'<path d="M7 8h10l3 13H4ZM8 8V6a4 4 0 0 1 8 0v2M5 21h14M12 12v5"/>',rope:'<path d="M8 20C-4 8 7-2 14 5c8 8-2 19-8 11-3-4 3-11 7-7s-1 10-5 7M15 16l7 6"/>',glass:'<path d="M9 2h6v6l4 5v9H5v-9l4-5ZM9 5h6M5 15h14"/>',arrow:'<path d="M4 12h16M14 6l6 6-6 6"/>',check:'<path d="m5 12 5 5L21 5"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 1 1 5 2c-2 1-2 2-2 3M12 17h.01"/>',bag:'<path d="M7 6V4h10v2M6 6h12l2 16H4ZM8 12h8v6H8ZM8 6v3M16 6v3"/>'};
const icon=(id,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[id]||icons.paper}</svg>`;
const button=(action,label,cls='button',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const avatar=name=>`<span class="portrait ${name==='Dina'?'dina':'tamatem'}" aria-hidden="true"></span>`;
let meta;
function refreshMeta(){meta={intro:['01',t("Die Lumenblüte"),'Dina'],research:['01',t("Der gemeinsame Arbeitstisch"),'Dina'],illness:['02',t("Als das Licht kühler wurde"),'Tamatem'],resolve:['03',t("Der leere Rucksack"),'Tamatem'],pack:['04',t("Was Dina vorbereitet hat"),'Tamatem'],threshold:['05',t("Hinter der letzten Laterne"),'Tamatem'],river:['06',t("Der bewegliche Stamm"),'Tamatem'],'river-crossing':['06',t("Über dem Wasser"),'Tamatem'],'river-complete':['06',t("Das andere Ufer"),'Tamatem'],garden:['07',t('Der Garten ohne Wasser'),'Tamatem'],'garden-complete':['08',t('Die Quelle wieder verbinden'),'Tamatem']};}

function persist(){savedAt=new Date().toISOString();try{localStorage.setItem(KEY,JSON.stringify({state,savedAt}));storageAvailable=true;}catch{storageAvailable=false;}}
function dispatch(action){const old=state.stage;state=reduce(state,action);persist();render();if(old!==state.stage){$('#main').focus({preventScroll:true});window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4300);}
function openModal(content){$('#modal-body').innerHTML=content;if(!$('#modal').open)$('#modal').showModal();$('#modal-body').scrollTop=0;}
function closeModal(){$('#modal').close();}
function heading(kicker,title){return `<p class="eyebrow">${kicker}</p><h2 id="modal-title">${title}</h2>`;}
function dialogueBox(name,text,small=''){return `<div class="dialogue-box">${avatar(name)}<div><div class="speaker">${esc(t(name))}${small?`<span>${esc(small)}</span>`:''}</div><p>${text}</p></div></div>`;}
function scene(image,caption,hotspots='',cls=''){return `<div class="scene ${cls}"><img src="${asset(image+'.png')}" alt="${esc(caption)}" draggable="false">${image==='river'&&state.river.secured?'<svg class="river-sling" viewBox="0 0 1672 941" aria-hidden="true"><path d="M660 655 Q460 745 180 640"/><path d="M660 655 Q460 745 180 640"/></svg>':''}${hotspots}<div class="scene-caption"><span class="scene-corner">${meta[state.stage][0]}</span><span>${esc(caption)}</span></div></div>`;}
function chapter(){const m=meta[state.stage];return `<div class="chapter-heading"><div><p class="eyebrow">${t("Kapitel 01 ")}<span class="eyebrow-line"></span>${t(" Alter 6")}</p><h1>${m[1]}</h1></div><span class="chapter-progress" aria-label="${t('Abschnitt {number} von 8',{number:m[0]})}">${m[0]}<span> / 08</span></span></div>`;}
function actor(){const name=meta[state.stage][2];return `<div class="actor-strip">${avatar(name)}<div><small>${t("Du spielst")}</small><strong>${t(name)}</strong></div><span class="save-indicator">${storageAvailable?t("Automatisch gespeichert"):t("Speichern nicht verfügbar")}</span></div>`;}
function tools(){return `<div class="scene-tools">${button('markers',icon('lens')+`<span>${t("Fundstücke zeigen")}</span>`,'tool-button '+(showMarkers?'active':''),'aria-pressed="'+showMarkers+'"')}${button('hint',icon('help')+`<span>${t("Hinweis")}</span>`,'tool-button')}</div>`;}
function intro(){return `<section class="cover"><img class="cover-art" src="${asset('workroom.png')}" alt="${esc(t("Tamatem und Dina recherchieren gemeinsam an ihrem Arbeitstisch."))}"><div class="cover-shade"></div><div class="cover-copy"><p class="eyebrow light">${t("Ein Comic-Adventure")}</p><h1>${t("Zwischen den Zeilen")}<span>.</span></h1><p class="cover-subtitle">${t("Sieben Abenteuer. Zwei Gefährten.")} ${t("Und die Frage, was es heißt, mutig zu sein.")}</p><div class="cover-start">${button('start',t("Die Lumenblüte beginnen ")+icon('arrow'),'button amber')}<span>${t("Prolog, Fluss und Quellgarten · Level 1 in Entwicklung")}</span></div></div><div class="cover-foot"><span>01 <i>${t("Die Lumenblüte")}</i></span><span>${t("Tamatem · 6 Jahre")}</span></div></section><div class="intro-note"><p>${t("Erkunde die Bilder, lies zwischen den Zeilen und verbinde die Hinweise.")}</p><span>${t("Mit Maus, Tastatur oder durch Antippen.")}</span></div>`;}
function research(){
 const marks=Object.entries(sources).map(([id,s],i)=>`<button class="hotspot ${state.read.includes(id)?'visited':''} ${showMarkers?'shown':''}" style="--x:${{field:68,travel:22,drawing:34,advert:86}[id]}%;--y:${{field:66,travel:87,drawing:67,advert:72}[id]}%" data-action="source" data-id="${id}" aria-label="${esc(s.title)} ${t("untersuchen")}"><span>${i+1}</span><b>${s.title}</b></button>`).join('');
 const shelf=`<div class="source-shelf">${Object.entries(sources).map(([id,s],i)=>`<button class="source-tab ${state.read.includes(id)?'read':''}" data-action="source" data-id="${id}"><span class="source-number">0${i+1}</span><span>${s.title}<small>${state.read.includes(id)?t("Gelesen"):t("Untersuchen")}</small></span>${state.read.includes(id)?icon('check'):icon(s.symbol)}</button>`).join('')}</div>`;
 const card=Object.entries(slots).map(([id,s])=>`<button class="evidence-slot ${state.assign[id]?'filled':''} ${state.committed?'confirmed':''}" data-action="slot" data-id="${id}" ${state.committed?'disabled':''}><span class="slot-label">${s.short}</span><span>${state.assign[id]?sources[state.assign[id]].title:s.title}</span><small>${state.assign[id]?(state.committed?t("Bestätigter Beleg"):t("Quelle ändern")):t("Beleg auswählen")}</small>${state.committed?icon('check'):icon('paper')}</button>`).join('');
 return `${chapter()}<div class="game-grid"><section class="stage-column">${actor()}${scene('workroom',t("Ein Nachmittag am gemeinsamen Arbeitstisch."),marks)}${tools()}${dialogueBox('Dina',state.committed?t("Drei Belege. Drei verschiedene Fragen. Jetzt wissen wir, was der Bericht wirklich trägt."):t("Der Artikel braucht mehr als eine schöne Geschichte. Was wissen wir über diese Blüte – und woher?"),t("Journalistin"))}<div class="scene-subnote">${state.read.length}${t(" von 4 Quellen gelesen")}</div></section><aside class="paper-panel"><div class="panel-heading"><span class="chapter-label">${t("Dinas Recherche")}</span>${icon('book')}</div><h2>${t("Was lässt sich belegen?")}</h2><p class="panel-intro">${t("Lies die Unterlagen auf dem Tisch. Ordne jeder Frage eine passende Quelle zu.")}</p>${shelf}<div class="research-divider"><span>${t("Die Recherchekarte")}</span><i></i></div><div class="evidence-slots">${card}</div>${feedback?`<p class="feedback" role="status">${esc(feedback)}</p>`:''}${state.committed?`<p class="success-line">${icon('check')}${t(" Die Karte ist vollständig.")}</p>${button('research-next',t("Die Mappe schließen ")+icon('arrow'),'button wide')}`:button('verify',t("Recherchekarte prüfen ")+icon('arrow'),'button wide')}</aside></div>`;
}
function illness(){return `${chapter()}<div class="game-grid"><section class="stage-column">${actor()}${scene('illness',t("Einige Stunden später. Das Fieber ist gestiegen."))}<div class="time-slip"><span>${t("Die Ärztin bleibt bei Dina.")}</span><span>${t("Der Bericht bietet eine mögliche Chance.")}</span></div>${dialogueBox('Tamatem',t("Gestern haben wir über diesen Bericht gelacht. Jetzt zähle ich die Zeilen, als könnte ich darin etwas übersehen haben."))} ${tools()}</section><aside class="paper-panel"><div class="panel-heading"><span class="chapter-label">${t("Ein anderer Abend")}</span>${icon('book')}</div><h2>${t("Was bleibt, wenn Wissen fehlt?")}</h2><p class="panel-intro">${t("Sprich mit Dina und der Ärztin, bevor du entscheidest, was du tust.")}</p><div class="conversation-list">${Object.entries(dialogue).map(([id,d])=>button('talk',`<span>${d.title}<small>${state.talked.includes(id)?t("Gespräch erneut lesen"):t("Zuhören")}</small></span>${icon(state.talked.includes(id)?'check':'arrow')}`,'conversation','data-id="'+id+'"')).join('')}</div><div class="aside-quote">${t("„Eine mögliche Hilfe. Keine Sicherheit.“")}<span>${t("Die Ärztin")}</span></div>${button('illness-next',t("Zurück zum Arbeitstisch ")+icon('arrow'),'button wide',heardEssentials(state)?'':'disabled')}<p class="microcopy">${heardEssentials(state)?t("Du weißt, wer sich um Dina kümmert."):t("Höre zuerst Dina und der Ärztin zu.")}</p></aside></div>`;}
function resolve(){return `${chapter()}<div class="game-grid"><section class="stage-column">${actor()}${scene('workroom',t("Der Raum ist derselbe. Nichts fühlt sich mehr so an."),'','evening')}${dialogueBox('Tamatem',t("Ich kann den Weg beschreiben. Ich kann die Blüte erkennen. Aber ich kann nicht ausrechnen, ob ich rechtzeitig zurück bin."))}<div class="narrative-note">${t("Der leere Rucksack steht unter dem Tisch.")} ${t("Zum ersten Mal fühlt sich Vorbereitung nicht wie Sicherheit an.")}</div>${tools()}</section><aside class="paper-panel"><div class="panel-heading"><span class="chapter-label">${t("Eine Entscheidung")}</span>${icon('bag')}</div><h2>${t("Was sagst du dir selbst?")}</h2><p class="panel-intro">${t("Du musst noch nicht furchtlos sein.")}</p><div class="choice-list">${button('choose',t("„Ich habe Angst, dass ich zu spät komme.“"),'choice '+(state.choice==='fear'?'selected':''),'data-id="fear" aria-pressed="'+(state.choice==='fear')+'"')}${button('choose',t("„Ich muss zuerst den Bericht verstehen.“"),'choice '+(state.choice==='research'?'selected':''),'data-id="research" aria-pressed="'+(state.choice==='research')+'"')}</div>${state.choice?`<p class="choice-response">${state.choice==='fear'?t("Die Angst verschwindet nicht. Aber sie hat jetzt einen Namen."):t("Wenn er die Zeilen noch einmal prüft, werden seine Hände ruhiger. Für einen Moment.")}</p>`:''}${button('resolve-next',t("Den Rucksack vorbereiten ")+icon('arrow'),'button wide',state.choice?'':'disabled')}<p class="microcopy">${t("Diese Entscheidung bleibt in deinem Spielstand.")}</p></aside></div>`;}
function pack(){const inventory=ITEM_IDS.map(id=>`<button class="inventory-item ${state.packed.includes(id)?'packed':''}" data-action="item" data-id="${id}" aria-label="${items[id].title}${state.packed.includes(id)?t(", eingepackt"):''}">${icon(items[id].symbol)}<span>${items[id].title}</span><small>${state.packed.includes(id)?t("Eingepackt"):t("Untersuchen")}</small>${state.packed.includes(id)?icon('check','item-check'):''}</button>`).join('');return `${chapter()}<div class="game-grid"><section class="stage-column">${actor()}${scene('workroom',t("Was du brauchst, liegt bereits vor dir."),'','evening')}${dialogueBox('Dina',t("Ich habe den Bericht geprüft. Ob der Garten noch dort ist, weiß ich nicht. Und du nimmst Hilfe an, wenn du welche findest.")) }<div class="inventory-heading"><span>${t("Reiseausrüstung")}</span><small>${state.packed.length}${t(" / 4 eingepackt")}</small></div><div class="inventory">${inventory}</div>${tools()}</section><aside class="paper-panel"><div class="panel-heading"><span class="chapter-label">${t("Vor dem Aufbruch")}</span>${icon('bag')}</div><h2>${t("Wissen wiegt fast nichts.")}</h2><p class="panel-intro">${t("Aber es muss mit. Übernimm Dinas Recherchekarte und packe die vier Gegenstände ein.")}</p>${button('take-note',`<span>${icon('book')}<b>${t("Dinas Recherchemappe")}</b><small>${state.noteTaken?t("Im Notizbuch übernommen"):t("Karte ansehen und mitnehmen")}</small></span>${icon(state.noteTaken?'check':'arrow')}`,'note-card '+(state.noteTaken?'taken':''))}<ul class="packing-list">${ITEM_IDS.map(id=>`<li class="${state.packed.includes(id)?'done':''}">${icon(state.packed.includes(id)?'check':items[id].symbol)}<span>${items[id].title}</span></li>`).join('')}</ul>${button('depart',t("Zum Waldrand ")+icon('arrow'),'button wide',readyToLeave(state)?'':'disabled')}<p class="microcopy">${readyToLeave(state)?t("Die Ärztin kennt deinen Weg und bleibt bei Dina."):t("Karte und Ausrüstung müssen vollständig sein.")}</p></aside></div>`;}
function threshold(){return `${chapter()}<div class="game-grid"><section class="stage-column">${actor()}${scene('threshold',t("Hinter dem letzten Dorflicht beginnt der Wald."))}<div class="owl-dialogue"><span class="owl-monogram" aria-hidden="true">O</span><div><span class="speaker">${t("Oris ")}<span>${t("Eine unerwartete Begleiterin")}</span></span><p>${t("„Du trägst sehr viel Entschlossenheit für so wenig Gepäck.“")}</p></div></div>${dialogueBox('Tamatem',t("„Die wiegt nichts.“"))}<p class="owl-reply">${t("„Das sagen die meisten, bevor sie sie brauchen.“")}</p>${tools()}</section><aside class="paper-panel"><div class="panel-heading"><span class="chapter-label">${t("Die Schwelle")}</span>${icon('map')}</div><h2>${t("Allein aufbrechen.")} ${t("Gemeinsam weiter.")}</h2><p class="panel-intro">${t("Die Eule sieht dich an, als hätte sie mit dir gerechnet.")}</p><div class="choice-list">${button('owl',t("„Begleitest du mich? Ich kenne den Wald nicht.“"),'choice','data-id="ask"')}${button('owl',t("„Kennst du den Weg zum Glasberg?“"),'choice','data-id="directions"')}</div><p class="microcopy">${t("Wie Tamatem Hilfe annimmt, gehört zu seiner Geschichte.")}</p></aside></div>`;}
function river(){
 const r=state.river;
 const marks=[['inspect',t("Stamm untersuchen"),56,51],['scout',t("Oris zur Gegenseite schicken"),13,12],['loop',t("Halteschlaufe ansehen"),40,70],['anchor',t("Öse ansehen"),10,67]].map(([id,label,x,y],i)=>`<button class="hotspot ${showMarkers?'shown':''}" style="--x:${x}%;--y:${y}%" data-action="river-${id}" aria-label="${esc(t(label))}"><span>${i+1}</span><b>${t(label)}</b></button>`).join('');
 const securing=r.secured?'<div class="river-secured" role="status">'+icon('check')+t('Stoffschlinge befestigt · Übergang gesichert')+'</div>':'';
 return `${chapter()}<div class="game-grid"><section class="stage-column">${actor()}${scene('river',t(r.secured?'Der Stamm ist gesichert. Der Weg liegt vor euch.':'Der Stamm reicht hinüber. Aber er bewegt sich.'),marks+securing,'river-scene')}${tools()}${dialogueBox('Tamatem',r.secured?t("Er reicht nicht nur hinüber. Jetzt bleibt er auch liegen."):state.owlChoice==='ask'?t("Oris, ich brauche deinen Blick von oben. Meiner endet gerade am Wasser."):t("Der Weg geht hier weiter. Die Frage ist nur: wie sicher?"))}<div class="inventory-heading"><span>${t("Reiseausrüstung")}</span></div><div class="inventory">${ITEM_IDS.map(id=>button('river-item',`${icon(items[id].symbol)}<span>${items[id].title}</span><small>${id==='sling'?(r.secured?t("Am Stamm befestigt"):r.slingSelected?t("Ausgewählt"):t("Auswählen")):t("Untersuchen")}</small>`,'inventory-item '+(id==='sling'&&r.slingSelected?'packed':''),'data-id="'+id+'"'+(id==='sling'?' aria-pressed="'+r.slingSelected+'"':''))).join('')}</div></section><aside class="paper-panel"><div class="panel-heading"><span class="chapter-label">${t("Der Fluss")}</span>${icon('map')}</div><h2>${t("Ein Weg ist noch keine Brücke.")}</h2><p class="panel-intro">${t("Untersuche den Übergang. Oris kann die andere Seite prüfen. Deine Ausrüstung bleibt dir erhalten.")}</p><div class="river-actions">${button('river-inspect',t("Stamm untersuchen"),'conversation')}${button('river-scout',t("Oris zur Gegenseite schicken"),'conversation')}${button('river-loop',r.loopAttached?t("Schlinge an der Halteschlaufe"):t("Halteschlaufe ansehen"),'conversation')}${button('river-anchor',r.loopAttached&&!r.secured?t("Schlinge an der Öse befestigen"):t("Öse ansehen"),'conversation')}</div><ul class="packing-list"><li class="${r.inspected?'done':''}">${icon(r.inspected?'check':'lens')}<span>${t("Seitliche Bewegung untersucht")}</span></li><li class="${r.farBankChecked?'done':''}">${icon(r.farBankChecked?'check':'map')}<span>${t("Gegenseitige Auflage geprüft")}</span></li><li class="${r.secured?'done':''}">${icon(r.secured?'check':'rope')}<span>${t("Stamm gegen Bewegung gesichert")}</span></li></ul>${feedback?`<p class="feedback" role="status">${esc(t(feedback))}</p>`:''}${button('river-cross',r.secured?t("Den gesicherten Stamm überqueren"):t("Überquerung versuchen"),'button wide')}<p class="microcopy">${t("Kein Zeitdruck. Ein Fehlversuch verliert keine Gegenstände.")}</p></aside></div>`;
}
function riverCrossing(){const panel=state.river.crossingPanel;return `${chapter()}<section class="crossing-panel">${scene('river',panel?t("Oris wartet am anderen Ufer."):t("Ein Schritt. Dann der nächste."),'','river-scene crossing-view crossing-view-'+panel)}<div class="paper-panel"><p class="eyebrow">${t("Überquerung")}</p><h2>${panel?t("Fester Boden."):t("Über dem Wasser.")}</h2><p>${panel?t("Tamatem erreicht das andere Ufer. Hinter ihm rauscht der Fluss; vor ihm steigt der Weg zum Glasberg an."):t("Die Schlinge hält den Stamm ruhig. Tamatem setzt vorsichtig einen Fuß vor den anderen. Oris fliegt voraus und wartet, bis er nachkommt.")}</p>${button('river-panel',panel?t("Am anderen Ufer ankommen"):t("Weiter über den Stamm"),'button wide')}</div></section>`;}
function riverComplete(){return `${chapter()}<section class="ending-panel">${scene('river',t("Der Fluss liegt hinter euch. Der Glasberg wartet."),'','river-scene crossing-view crossing-view-1')}<div class="ending-copy"><p class="eyebrow">${t("Flussübergang geschafft")}</p><h2>${t("Gemeinsam hinüber.")}</h2><p>${t("„Deine Entschlossenheit ist trocken geblieben“, sagt Oris.")}</p><p>${t("„Sie wiegt ja auch nichts.“")}</p><p>${t("Deine Entscheidungen und der gesicherte Übergang bleiben im Spielstand erhalten.")}</p><div class="next-chapter"><span>${t("Danach folgt")}</span><strong>${t("Der Quellgarten")}</strong><small>${t('Der Hüter des Glasbergs wartet auf euch.')}</small></div><div class="ending-buttons">${button('garden-start',t('Zum Quellgarten'),'button')}${button('notebook',t("Notizbuch ansehen"),'button')}${button('export',t("Spielstand sichern"),'button secondary')}</div></div></section>`;}
function channelBoard(rotations,preview=false){
 const g=state.garden,ready=g.metGuardian&&g.inspected;
 const trace=(g.tested||preview)?traceChannels(rotations):null;
 const sideNames=[t('Oben'),t('Rechts'),t('Unten'),t('Links')];
 const ends=[[50,0],[100,50],[50,100],[0,50]];
 const tiles=rotations.map((rotation,index)=>{
  const openings=channelOpenings(index,rotations),[a,b]=openings.map(side=>ends[side]);
  const line=`M${a[0]} ${a[1]} L50 50 L${b[0]} ${b[1]}`;
  const step=trace?.path.indexOf(index)??-1;
  const previous=step>0?trace.path[step-1]:null;
  const entry=step===0?3:previous===null?null:({'-3':0,'1':1,'3':2,'-1':3})[previous-index];
  const flowEnds=step>=0?(openings[0]===entry?[a,b]:[b,a]):[a,b];
  const flowLine=`M${flowEnds[0][0]} ${flowEnds[0][1]} L50 50 L${flowEnds[1][0]} ${flowEnds[1][1]}`;
  const stop=trace?.stop?.tile===index?ends[trace.stop.side].map(coordinate=>Math.min(90,Math.max(10,coordinate))):null;
  const label=t('Kanalplatte {number}: {openings}.',{number:index+1,openings:openings.map(side=>sideNames[side]).join(' / ')});
  const drawing=`<span class="tile-number" aria-hidden="true">${index+1}</span><svg viewBox="0 0 100 100" aria-hidden="true"><path class="channel-groove" d="${line}"/>${step>=0?`<path class="channel-water ${preview?'preview-water':''}" style="animation-delay:${step*.16}s" d="${flowLine}"/><text class="channel-check" x="82" y="21">✓</text>`:''}${stop?`<path class="channel-break" d="M${stop[0]-6} ${stop[1]-6}l12 12m0 -12l-12 12"/>`:''}</svg>`;
  return preview?`<div class="channel-tile preview-tile" aria-label="${esc(label)}">${drawing}</div>`:`<button class="channel-tile" data-action="garden-rotate" data-id="${index}" aria-label="${esc(label+' '+t('Eine Vierteldrehung im Uhrzeigersinn.'))}" ${!ready||g.watered?'disabled':''}>${drawing}</button>`;
 }).join('');
 return `<div class="channel-board ${preview?'channel-preview':''}" ${preview?'role="img" aria-label="'+esc(t('Vorschau des vollständigen Wasserwegs.'))+'"':''}><div class="channel-source"><span>${t('Quelle')}</span><span aria-hidden="true">→</span></div><div class="channel-grid"><span class="channel-inlet" aria-hidden="true">→</span>${tiles}</div><div class="channel-basin"><span aria-hidden="true">↓</span><span>${t('Wurzelbecken')}</span></div></div>`;
}
function garden(){
 const g=state.garden,ready=g.metGuardian&&g.inspected;
 const trace=g.tested?traceChannels(g.rotations):null;
 const marks=[['guardian',t('Mit dem Hüter sprechen'),64,29],['inspect',t('Wasseranlage untersuchen'),41,57]].map(([id,label,x,y],index)=>`<button class="hotspot ${showMarkers?'shown':''}" style="--x:${x}%;--y:${y}%" data-action="garden-${id}" aria-label="${esc(label)}"><span>${index+1}</span><b>${label}</b></button>`).join('');
 return `${chapter()}<div class="game-grid"><section class="stage-column">${actor()}${scene('garden-dry',t('Die Quelle fließt. Der Garten bleibt trocken.'),marks,'garden-scene')}${tools()}<div class="owl-dialogue guardian-dialogue">${icon('leaf')}<div><span class="speaker">${t('Hüter')}</span><p>${g.metGuardian?t('„Verbinde die Quelle mit dem Wurzelbecken. Die Blüten können nur leben, wenn ihre Wurzeln Wasser bekommen.“'):t('„Ihr nennt es Hilfe, wenn ihr etwas mitnehmt.“')}</p></div></div>${dialogueBox('Tamatem',g.inspected?t('Das Wasser ist da. Nur sein Weg ist unterbrochen.'):t('Dann zeig mir, was hier fehlt.'))}<div class="river-actions">${button('garden-guardian',g.metGuardian?t('Noch einmal mit dem Hüter sprechen'):t('Mit dem Hüter sprechen'),'conversation')}${button('garden-inspect',t('Wasseranlage untersuchen'),'conversation')}${button('garden-lens',t('Mit der Lupe nach Spuren suchen'),'conversation')}</div>${g.inspected?`<p class="garden-observation">${t('Feuchte Spuren enden an den verdrehten Kanälen. Der letzte Abfluss liegt über den trockenen Wurzeln.')}</p>`:''}</section><aside class="paper-panel"><div class="panel-heading"><span class="chapter-label">${t('Sechs Kanäle')}</span>${icon('leaf')}</div><h2>${t('Ein Garten braucht mehr als eine Blüte.')}</h2><p class="panel-intro">${t('Verbinde die Quelle links oben mit dem Becken unter der linken unteren Platte. Jede Platte dreht sich pro Antippen um eine Vierteldrehung.')}</p>${!ready?`<p class="feedback">${t('Sprich mit dem Hüter und untersuche die Wasseranlage. Danach kannst du die Platten drehen.')}</p>`:''}${channelBoard(g.rotations)}<p class="microcopy">${t('Die kleinen Zahlen bezeichnen die sechs Platten. Die Anordnung bleibt in jeder Sprache gleich.')}</p>${trace?`<p class="feedback" role="status">${t('Das Wasser erreicht {count} von 6 Platten. Unterbrechung an Platte {number}.',{count:trace.path.length,number:trace.stop.tile+1})}</p>`:''}${button('garden-test',t('Wasser freigeben und prüfen'),'button wide',ready?'':'disabled')}<p class="microcopy">${t('Kein Wasserverbrauch, kein Zeitlimit. Du kannst jede Verbindung beliebig oft prüfen.')}</p>${g.solutionPreview?`<section class="solution-preview"><h3>${t('Lösungsvorschau')}</h3><p>${t('Diese Vorschau verändert deine Platten noch nicht.')}</p>${channelBoard(CHANNEL_SOLUTION,true)}${button('garden-apply-preview',t('Vorschau übernehmen'),'button secondary wide',ready?'':'disabled')}${button('garden-hide-preview',t('Vorschau schließen'),'text-button')}</section>`:''}</aside></div>`;
}
function showGuardian(){
 dispatch({type:'GARDEN_TALK'});
 openModal(`${heading(t('Der Quellgarten'),t('Was der Hüter beschützt'))}<div class="dialogue-transcript">${gardenDialogue.map(([name,text])=>`<div class="transcript-line ${name==='Tamatem'?'child-line':''}"><strong>${esc(t(name))}</strong><p>${esc(text)}</p></div>`).join('')}</div>${button('close',t('Zurück zum Garten'),'button wide')}`);
}
function gardenComplete(){return `${chapter()}<section class="garden-success">${scene('garden-wet',t('Wasser erreicht die Wurzeln. Der Hüter öffnet die Kammer.'),'','garden-scene')}<div class="garden-finale"><div class="paper-panel"><p class="eyebrow">${t('Der Garten lebt wieder')}</p><h2>${t('Helfen heißt auch: etwas erhalten.')}</h2><p>${t('Wasser rinnt durch alle sechs Kanäle. Blätter richten sich auf, und der Hüter nimmt den Arm von der Tür.')}</p><div class="owl-dialogue guardian-dialogue">${icon('leaf')}<div><span class="speaker">${t('Hüter')}</span><p>${t('„Du hast dem Garten etwas zurückgegeben. Die Kammer steht dir offen.“')}</p></div></div><p>${t('Tamatem nimmt Dinas Recherchekarte zur Hand. Hinter der offenen Tür wartet die lebende Lumenblüte.')}</p><div class="next-chapter"><span>${t('Danach folgt')}</span><strong>${t('Die Blütenkammer')}</strong><small>${t('Dieser Teil ist noch in Entwicklung.')}</small></div><div class="ending-buttons">${button('notebook',t('Notizbuch ansehen'),'button')}${button('export',t('Spielstand sichern'),'button secondary')}</div></div><aside class="paper-panel"><h3>${t('Der vollständige Wasserweg')}</h3>${channelBoard(state.garden.rotations)}<p class="success-line">${icon('check')}${t('Garten bewässert · Kammer geöffnet')}</p></aside></div></section>`;}
function languagePicker(){return `<label class="language-picker"><span>${t('Sprache')}</span><select class="language-select" aria-label="${t('Sprache wählen')}">${Object.entries(LANGUAGES).map(([code,info])=>`<option value="${code}" lang="${code}" dir="${info.dir}" ${getLanguage()===code?'selected':''}>${info.label}</option>`).join('')}</select></label>`;}
function renderShell(){
 document.documentElement.lang=getLanguage();document.documentElement.dir=LANGUAGES[getLanguage()].dir;
 for(const element of document.querySelectorAll('[data-i18n]'))element.textContent=t(element.dataset.i18n);
 for(const element of document.querySelectorAll('[data-i18n-aria]'))element.setAttribute('aria-label',t(element.dataset.i18nAria));
 $('#language-control').innerHTML=languagePicker();
 $('#offline-status').textContent=t(offlineMessage);
 document.querySelector('meta[name="description"]').content=t('Tamatem & Dina – ein farbiges Comic-Adventure. Spiele den Prolog, den Fluss und den Quellgarten.');
}
function render(){const focused=document.activeElement;const action=focused?.closest('#main [data-action]');const focusedAction=action?{action:action.dataset.action,id:action.dataset.id}:null;refreshMeta();refreshContent();renderShell();const renders={intro,research,illness,resolve,pack,threshold,river,'river-crossing':riverCrossing,'river-complete':riverComplete,garden,'garden-complete':gardenComplete};$('#main').innerHTML=renders[state.stage]();$('#notebook-button').disabled=state.stage==='intro';document.title=(state.stage==='intro'?t("Tamatem & Dina"):meta[state.stage][1])+t(" – Zwischen den Zeilen");if(focusedAction){const next=[...$('#main').querySelectorAll('[data-action]')].find(element=>element.dataset.action===focusedAction.action&&element.dataset.id===focusedAction.id);next?.focus({preventScroll:true});}}
function showSource(id){if(!sources[id])return;dispatch({type:'READ',id});const s=sources[id];openModal(`${heading(t("Quelle · ")+s.tag,s.title)}<div class="document-sheet"><div class="document-seal">${icon(s.symbol)}</div><p class="document-byline">${s.kicker}</p><p class="document-date">${s.date}</p>${s.text.map(t=>`<p>${esc(t)}</p>`).join('')}</div><p class="character-comment"><strong>${t("Dina")}</strong> „${esc(s.comment)}“</p>${state.committed?'':`<div class="document-actions"><p>${t("Auf der Recherchekarte verwenden für:")}</p>${Object.entries(slots).map(([k,v])=>button('assign',v.short,'button secondary','data-slot="'+k+'" data-id="'+id+'"')).join('')}</div>`}`);}
function showSlot(id){const s=slots[id];openModal(`${heading(t('Die Recherchekarte'),s.title)}<p class="modal-intro">${s.description}</p><div class="source-chooser">${Object.entries(sources).map(([sid,src])=>button(state.read.includes(sid)?'assign':'source',`${icon(src.symbol)}<span>${src.title}<small>${state.read.includes(sid)?t("Als Beleg einsetzen"):t("Zuerst lesen")}</small></span>${icon('arrow')}`,'conversation','data-id="'+sid+'" data-slot="'+id+'"')).join('')}</div>`);}
function showTalk(id){const d=dialogue[id];dispatch({type:'TALK',id});openModal(`${heading(t("Dinas Zimmer"),d.title)}<div class="dialogue-transcript">${d.lines.map(([name,text])=>`<div class="transcript-line ${name==='Tamatem'?'child-line':''}"><strong>${t(name)}</strong><p>${esc(text)}</p></div>`).join('')}</div>${button('close',t("Zurück ins Zimmer ")+icon('arrow'),'button wide')}`);}
function showItem(id){const i=items[id];openModal(`${heading(t("Reiseausrüstung"),i.title)}<div class="item-illustration">${icon(i.symbol)}</div><p class="item-tagline">${i.line}</p><p class="modal-intro">${i.detail}</p>${state.packed.includes(id)?`<p class="success-line">${icon('check')}${t(" Bereits im Rucksack.")}</p>`:button('pack',t("In den Rucksack legen ")+icon('bag'),'button wide','data-id="'+id+'"')}`);}
function showNote(){openModal(`${heading(t("Dinas Recherchekarte"),t("Drei Fragen. Drei Belege."))}<div class="notebook-entries">${Object.entries(slots).map(([k,v])=>`<article><span class="eyebrow">${v.short}</span><h3>${sources[state.assign[k]].title}</h3><p>${sources[state.assign[k]].observation}</p></article>`).join('')}</div><p class="modal-intro">${t("Tamatem liest die Karte und übernimmt die Angaben in sein Notizbuch.")}</p>${state.noteTaken?`<p class="success-line">${t("Die Karte ist bereits übernommen.")}</p>`:button('confirm-note',t("Ins Notizbuch übernehmen ")+icon('book'),'button wide')}`);}
function notebook(){let content='';if(state.stage==='research'||state.stage==='illness'||state.stage==='resolve'){content=`<p class="modal-intro">${state.stage==='research'?t("Dinas Recherche am Arbeitstisch."):t("Dinas Karte liegt noch in der Mappe. Tamatem muss sie vor dem Aufbruch selbst lesen.")}</p>`;if(state.stage==='research')content+=state.read.length?state.read.map(id=>`<article><h3>${sources[id].title}</h3><p>${sources[id].observation}</p></article>`).join(''):`<p>${t("Noch keine Quellen untersucht.")}</p>`;}if(state.noteTaken)content+=Object.entries(slots).map(([k,v])=>`<article><span class="eyebrow">${v.short}</span><h3>${sources[state.assign[k]].title}</h3><p>${sources[state.assign[k]].observation}</p></article>`).join('');if(['pack','threshold','river','river-crossing','river-complete','garden','garden-complete'].includes(state.stage))content+=`<article><span class="eyebrow">${t("Eine Entscheidung")}</span><h3>${state.choice==='fear'?t("Die Angst benennen"):t("Am Bericht festhalten")}</h3><p>${state.choice==='fear'?t("Ich habe Angst, dass ich zu spät komme."):t("Ich muss zuerst den Bericht verstehen.")}</p></article>`;if(state.owlChoice)content+=`<article><span class="eyebrow">${t("Am Waldrand")}</span><h3>${t("Oris")}</h3><p>${state.owlChoice==='ask'?t("Ich habe sie gebeten, mich zu begleiten."):t("Ich habe sie nach dem Weg gefragt. Sie fliegt voraus.")}</p></article>`;if(state.river.inspected)content+=`<article><h3>${t("Der Fluss")}</h3><p>${state.river.secured?t("Die Stoffschlinge hält den Stamm. Oris hat die andere Auflage geprüft."):t("Der Stamm bewegt sich seitlich. Die Öse am Ufer steht fest.")}</p></article>`;if(state.garden.inspected)content+=`<article><h3>${t('Der Quellgarten')}</h3><p>${state.garden.watered?t('Alle sechs Kanäle versorgen die Wurzeln. Der Hüter hat die Kammer geöffnet.'):t('Das Wasser muss von der Quelle durch sechs Platten zum Wurzelbecken fließen.')}</p></article>`;openModal(`${heading(t("Beobachtungen & Entscheidungen"),t("Das Notizbuch"))}<div class="notebook-entries">${content||`<p>${t("Die erste Seite ist noch leer.")}</p>`}</div>`);}
function showHint(){const list=hints[state.stage];if(!list){toast(t("Beginne das Abenteuer. Hinweise stehen dir während des Spiels zur Verfügung."));return}dispatch({type:'HINT'});const level=state.hints[state.stage]||1;openModal(`${heading(t('Rätselhilfe · Stufe {level} von 3',{level}),t("Ein Gedanke für den Weg"))}<p class="hint-copy">${list[level-1]}</p><p class="microcopy">${t("Hinweise verändern deine Geschichte nicht.")}</p>${level<3?button('hint',t("Konkreteren Hinweis zeigen"),'button secondary'):state.stage==='garden'?button('garden-preview',t('Lösungsvorschau ansehen'),'button secondary'):''}`);}
function menu(){const time=savedAt?new Intl.DateTimeFormat(getLanguage(),{hour:'2-digit',minute:'2-digit'}).format(new Date(savedAt)):'–';openModal(`${heading(t("Tamatem & Dina"),t("Eine Pause ist erlaubt."))}<p class="modal-intro">${storageAvailable?t("Dein Fortschritt wird nach jeder Handlung auf diesem Gerät gespeichert."):t("Der Browser konnte den lokalen Spielstand nicht speichern. Sichere ihn als Datei, bevor du schließt.")}</p><div class="menu-status"><span>${t("Aktueller Abschnitt")}</span><strong>${meta[state.stage][1]}</strong><small>${t("Zuletzt gespeichert: ")}${esc(time)}</small></div>${languagePicker()}<div class="menu-actions">${button('close',t("Weiterspielen ")+icon('arrow'),'button wide')}${button('export',t("Spielstand als Datei sichern"),'button secondary wide')}${button('import',t("Spielstand aus Datei laden"),'button secondary wide')}${button('offline-info',t("Offline auf Laptop & iPhone"),'button secondary wide')}${button('restart-confirm',t("Von vorn beginnen"),'text-button')}</div>`);}
function exportSave(){const blob=new Blob([JSON.stringify({game:'tamatem-dina-prolog',state,savedAt},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='tamatem-dina-spielstand.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(t("Spielstand als Datei bereitgestellt."));}
function offlineInfo(){openModal(`${heading(t("Dein Abenteuer für unterwegs"),t("Ohne Netz weiterspielen."))}<p class="modal-intro">${globalThis.TD_STANDALONE?t("Diese Datei enthält alle Bilder, Texte und Spielfunktionen des spielbaren Abschnitts. Auf dem Laptop kannst du sie direkt im Browser öffnen."):t("Öffne diese Version einmal mit Internet und warte auf „Offline bereit“ am unteren Seitenrand. Dann sind die Dateien dieses Spielabschnitts auf dem Gerät gespeichert.")}</p><ol class="offline-instructions"><li><strong>${t("Auf dem iPhone")}</strong><p>${t("Öffne die Spieladresse in Safari. Wähle im Teilen-Menü „Zum Home-Bildschirm“ und öffne das Spiel anschließend über dieses Symbol. Lade es dort einmal vollständig.")}</p></li><li><strong>${t("Auf dem Laptop")}</strong><p>${globalThis.TD_STANDALONE?t("Bewahre diese HTML-Datei auf. Sie benötigt keinen zusätzlichen Server und keine laufende Internetverbindung."):t("Nutze denselben Browser und dieselbe Adresse. Eine Installation als App ist optional.")}</p></li><li><strong>${t("Dein Spielstand")}</strong><p>${t("Er liegt auf diesem Gerät. Über die Dateisicherung kannst du ihn auf ein anderes Gerät übertragen. Browser können lokale Daten löschen; die Datei bleibt deine zusätzliche Sicherung.")}</p></li></ol><p class="microcopy">${t("Die private Spieladresse kann beim erstmaligen Öffnen eine Anmeldung verlangen. Offline muss die Web-Version auf dem jeweiligen Gerät bereits vollständig geladen sein.")}</p>`);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;
 switch(a){
 case 'start':dispatch({type:'START'});break;
 case 'source':showSource(id);break;
 case 'slot':showSlot(id);break;
 case 'assign':feedback='';dispatch({type:'ASSIGN',slot:b.dataset.slot,id});closeModal();toast(t("Beleg auf der Recherchekarte vermerkt."));break;
 case 'verify':if(correctResearch(state)){feedback='';dispatch({type:'VERIFY'});toast(t("Dina hat die Recherchekarte fertiggestellt."));}else{const wrong=Object.keys(slots).filter(k=>state.assign[k]!=={property:'field',place:'travel',identity:'drawing'}[k]);feedback=wrong.some(k=>!state.assign[k])?t("Es fehlen noch Belege. Lies die Quellen und besetze alle drei Felder."):t("Mindestens ein Beleg beantwortet eine andere Frage. Prüfe besonders: ")+slots[wrong[0]].short+'.';render();}break;
 case 'research-next':feedback='';dispatch({type:'RESEARCH_NEXT'});break;
 case 'talk':showTalk(id);break;
 case 'illness-next':dispatch({type:'ILLNESS_NEXT'});break;
 case 'choose':dispatch({type:'CHOOSE',id});break;
 case 'resolve-next':dispatch({type:'RESOLVE_NEXT'});break;
 case 'item':showItem(id);break;
 case 'pack':dispatch({type:'PACK',id});closeModal();toast(items[id].title+t(" eingepackt."));break;
 case 'take-note':showNote();break;
 case 'confirm-note':dispatch({type:'TAKE_NOTE'});closeModal();toast(t("Dinas Karte ist jetzt in Tamatems Notizbuch."));break;
 case 'depart':dispatch({type:'DEPART'});break;
 case 'owl':dispatch({type:'OWL_CHOICE',id});break;
 case 'river-inspect':dispatch({type:'RIVER_INSPECT'});feedback=t(state.river.secured?'Die Schlinge verbindet Stamm und Öse. Der Stamm bewegt sich nicht mehr seitlich.':'Der Stamm ist lang genug. Das Problem ist seine seitliche Bewegung.');render();break;
 case 'river-scout':dispatch({type:'RIVER_SCOUT'});feedback=t(state.river.secured?'Oris prüft noch einmal: „Die Auflage hält. Und deine Schlinge auch.“':'Oris fliegt hinüber und kehrt zurück: „Die andere Auflage ist fest. Aber hier bewegt sich der Stamm noch.“');render();break;
 case 'river-item':if(id==='sling'){dispatch({type:'RIVER_SLING'});feedback=state.river.secured?t("Die Stoffschlinge bleibt am Stamm. Sie sichert den Übergang."):state.river.loopAttached?t("Die Schlinge liegt an der Halteschlaufe. Verbinde sie jetzt mit der Öse."):state.river.slingSelected?t("Die Stoffschlinge ist ausgewählt. Wo könnte sie die Bewegung begrenzen?"):t("Die Stoffschlinge ist wieder im Rucksack.");}else feedback=id==='lens'?t("Die Lupe zeigt die abgeriebene Stelle. Festhalten kann sie den Stamm nicht."):t("Das hilft hier nicht gegen die seitliche Bewegung. Der Gegenstand bleibt im Rucksack.");render();break;
 case 'river-loop':if(state.river.secured)feedback=t("Die Stoffschlinge bleibt am Stamm. Sie sichert den Übergang.");else if(!state.river.inspected)feedback=t("Untersuche zuerst, warum sich der Stamm bewegt.");else if(!state.river.farBankChecked)feedback=t("Bevor du etwas befestigst: Lass Oris die andere Auflage prüfen.");else if(!state.river.slingSelected)feedback=t("Eine alte Halteschlaufe liegt um den Stamm. Wähle einen passenden Gegenstand aus deinem Rucksack.");else{dispatch({type:'RIVER_LOOP'});feedback='Die Stoffschlinge liegt an der Halteschlaufe. Verbinde sie jetzt mit der Öse.';}render();break;
 case 'river-anchor':if(state.river.loopAttached){dispatch({type:'RIVER_ANCHOR'});feedback=t("Die Schlinge verbindet Stamm und Öse. Der Stamm bewegt sich nicht mehr seitlich.");}else feedback=t("Die alte Öse sitzt fest im Fels. Sie könnte etwas halten.");render();break;
 case 'river-cross':if(state.river.secured){feedback='';dispatch({type:'RIVER_CROSS'});}else{feedback=t("Noch nicht. Der Stamm bewegt sich zu stark. Erst prüfen und sichern.");render();}break;
 case 'river-panel':dispatch({type:'RIVER_PANEL'});break;
 case 'garden-start':feedback='';dispatch({type:'GARDEN_START'});break;
 case 'garden-guardian':showGuardian();break;
 case 'garden-inspect':case 'garden-lens':dispatch({type:'GARDEN_INSPECT'});break;
 case 'garden-rotate':dispatch({type:'GARDEN_ROTATE',index:Number(id)});break;
 case 'garden-test':dispatch({type:'GARDEN_TEST'});break;
 case 'garden-preview':dispatch({type:'GARDEN_PREVIEW'});closeModal();break;
 case 'garden-apply-preview':dispatch({type:'GARDEN_APPLY_PREVIEW'});break;
 case 'garden-hide-preview':dispatch({type:'GARDEN_HIDE_PREVIEW'});break;
 case 'hint':showHint();break;
 case 'markers':showMarkers=!showMarkers;render();break;
 case 'notebook':notebook();break;
 case 'close':closeModal();break;
 case 'export':exportSave();break;
 case 'import':$('#import-file').click();break;
 case 'offline-info':offlineInfo();break;
 case 'restart-confirm':openModal(`${heading(t("Neuer Anfang"),t("Diesen Durchlauf neu beginnen?"))}<p class="modal-intro">${t("Der lokale Fortschritt wird ersetzt. Sichere vorher eine Datei, wenn du diesen Durchlauf behalten möchtest.")}</p><div class="menu-actions">${button('export',t("Vorher als Datei sichern"),'button secondary wide')}${button('restart',t("Ja, neu beginnen"),'button wide')}${button('menu',t("Zurück"),'text-button')}</div>`);break;
 case 'restart':state=initialState();feedback='';persist();closeModal();render();window.scrollTo(0,0);break;
 case 'menu':menu();break;
 }
});
$('#modal-close').addEventListener('click',closeModal);
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
$('#notebook-button').addEventListener('click',notebook);
$('#menu-button').addEventListener('click',menu);
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>128000)throw Error(t("Die Spielstanddatei ist zu groß."));const x=JSON.parse(await file.text());if(x.game!=='tamatem-dina-prolog')throw Error(t("Das ist kein Spielstand dieses Prologs."));const incoming=validateState(x.state);openModal(`${heading(t("Spielstand laden"),t("Diesen Fortschritt übernehmen?"))}<p class="modal-intro">${t("Abschnitt: ")}${esc(meta[incoming.stage][1])}${t(". Dein aktueller lokaler Fortschritt wird ersetzt.")}</p><div class="menu-actions">${button('confirm-import',t("Spielstand übernehmen"),'button wide')}${button('menu',t("Abbrechen"),'button secondary wide')}</div>`);const confirm=$('[data-action="confirm-import"]');confirm.addEventListener('click',()=>{state=incoming;feedback='';persist();closeModal();render();$('#main').focus();toast(t("Spielstand übernommen."));},{once:true});}catch(error){toast(t(error instanceof SyntaxError?t("Diese Datei konnte nicht gelesen werden."):error.message)||t('Diese Datei konnte nicht gelesen werden.'));}finally{e.target.value='';}});
async function setupOffline(){const status=$('#offline-status');if(globalThis.TD_STANDALONE){status.textContent=t(offlineMessage='Offline-Version · alles in dieser Datei');status.classList.add('ready');return}if(!('serviceWorker'in navigator)||!['https:','http:'].includes(location.protocol)){status.textContent=t(offlineMessage='Für Offline-Laden einmal über die Spieladresse öffnen');return}try{const reg=await navigator.serviceWorker.register('./sw.js');const ready=await navigator.serviceWorker.ready;const worker=ready.active;if(worker){const channel=new MessageChannel();channel.port1.onmessage=e=>{status.textContent=t(offlineMessage=e.data.ready?'Offline bereit · Spielabschnitt vollständig geladen':'Offline-Dateien noch nicht vollständig');status.classList.toggle('ready',!!e.data.ready)};worker.postMessage({type:'STATUS'},[channel.port2]);}reg.addEventListener('updatefound',()=>{const w=reg.installing;w?.addEventListener('statechange',()=>{if(w.state==='installed'&&navigator.serviceWorker.controller)toast(t("Eine neue Spielversion ist bereit. Sie wird beim nächsten Öffnen geladen."));});});}catch{status.textContent=t(offlineMessage='Offline-Laden nicht verfügbar · Spielstand als Datei sichern');}}
document.addEventListener('change',event=>{if(!event.target.matches('.language-select'))return;setLanguage(event.target.value);feedback='';closeModal();$('#toast').classList.remove('visible');render();$('#language-control .language-select').focus({preventScroll:true});});
render();setupOffline();
